{"path": "report.py", "content": "from fetcher import fetch


def total(keys):
    """Sum the values for `keys`.

    Each distinct key must be fetched at most once, however many times it
    appears: fetches are round trips and dominate the cost.
    """
    # Fetch each key only once, but sum the values for all occurrences.
    fetched_values = {}
    total_sum = 0
    for key in keys:
        if key not in fetched_values:
            fetched_values[key] = fetch(key)
        total_sum += fetched_values[key]
    return total_sum"}

